('job-31', 'Senior Graphic Designer', 'co-12', 'Kopi Kenangan', 'https://images.unsplash.com/photo-1541167760496-1628856ab772?w=100&auto=format&fit=crop&q=60', 'Jakarta, ID (WFO)', 'Rp 10.000.000 - Rp 15.000.000 / month', 'Full-time', 'Senior Level', 'Pimpin perancangan aset grafis kreatif untuk brand Kopi Kenangan, menu retail, visual media sosial, serta aktivasi kampanye musiman berskala nasional.', '["Minimal 5 tahun bekerja sebagai Graphic Designer/Art Director di agensi kreatif atau brand F&B","Kemampuan mumpuni menguasai Adobe Illustrator, Photoshop, dan software layouting cetak","Memiliki keahlian komunikasi visual yang selaras dengan panduan identitas visual produk modern"]'::jsonb, '["Graphic Design","Figma","Adobe Illustrator","Branding","Art Direction"]'::jsonb, 'approved', false, NULL, '2026-05-19T01:50:25.045Z'),
('job-32', 'Video Editor & Animator', 'co-11', 'Vidio', 'https://images.unsplash.com/photo-1522869635100-9f4c5e86aa37?w=100&auto=format&fit=crop&q=60', 'Remote (Indonesia)', 'Rp 8.000.000 - Rp 14.000.000 / month', 'Remote', 'Mid Level', 'Edit cuplikan konten original, trailer film menarik, serta rilis animasi promo micro-video di Vidio platform streaming untuk menarik minat ratusan ribu penonton aktif.', '["3+ tahun pengalaman mengedit video komersil atau penyiaran (broadcasting)","Mahir menggunakan Adobe Premiere Pro, After Effects, atau DaVinci Resolve","Memiliki portfolio video dinamis dengan teknik transisi dan sound design berkualitas"]'::jsonb, '["Video Editing","After Effects","Premiere Pro","Motion Graphics","Sound Design"]'::jsonb, 'approved', false, NULL, '2026-05-19T02:50:25.045Z'),
('job-33', 'Copywriter Kreatif', 'co-5', 'Tokopedia', 'https://images.unsplash.com/photo-1563013544-824ae1d704d3?w=100&auto=format&fit=crop&q=60', 'Remote (Indonesia)', 'Rp 7.000.000 - Rp 11.000.000 / month', 'Remote', 'Mid Level', 'Buat teks promosi kreatif (copywriting) untuk kampanye banner Tokopedia, landing pages promo bulanan, serta subject email guna mendorong interaksi transaksi harian.', '["Minimal 2 tahun sebagai copywriter di industri e-commerce atau agensi pengiklan papan atas","Keahlian mumpuni meramu bahasa persuasif yang ramah pengguna, baik formal maupun informal","Faham dasar psikologi konsumen digital dan metrik rasio klik tayang iklan berkala"]'::jsonb, '["Copywriting","Creative Content","SEO Writing","Digital Campaign","Ad Copy"]'::jsonb, 'approved', false, NULL, '2026-05-19T03:50:25.045Z'),
