('job-41', 'Audio Designer & Sound Engineer', 'co-11', 'Vidio', 'https://images.unsplash.com/photo-1522869635100-9f4c5e86aa37?w=100&auto=format&fit=crop&q=60', 'Jakarta, ID / Hybrid', 'Rp 9.000.000 - Rp 15.000.000 / month', 'Full-time', 'Mid Level', 'Poles efek suara latar belakang (foley, sound effects), mixing vokal jernih, serta lisensi audio musik latar penunjang promosi media digital.', ARRAY['3+ tahun bekerja di industri produksi musik, studio rekaman, atau pascaproduksi film', 'Menguasai software Pro Tools, FL Studio, Logic Pro, atau Ableton Live dengan piawai', 'Pemahaman mumpuni mengenai kompresi desibel audio, akustik ruang, serta eq balancing']::text[], ARRAY['Audio Engineering', 'Foley Sound', 'Logic Pro', 'Audio Mixing', 'Ableton Live']::text[], 'approved', false, NULL, '2026-05-19T11:50:25.045Z'),
('job-42', 'Creative Intern - Graphic Design', 'co-5', 'Tokopedia', 'https://images.unsplash.com/photo-1563013544-824ae1d704d3?w=100&auto=format&fit=crop&q=60', 'Jakarta, ID / Hybrid', 'Rp 3.500.000 - Rp 4.500.000 / month', 'Internship', 'Entry Level', 'Asah keahlian menatamu! Bantu tim desainer senior Tokopedia memotong visual produk merchant, merapikan aset vector banner, serta meramu kolase marketing.', ARRAY['Mahasiswa aktif tingkat akhir atau fresh-graduated jurusan Desain Komunikasi Visual (DKV)', 'Memiliki portofolio digital yang menampilkan dasar-dasar harmoni warna dan tipografi', 'Siap belajar cepat dan komunikatif berkontribusi ide baru saat brainstorming']::text[], ARRAY['Photoshop', 'Adobe Illustrator', 'Layouting', 'Teamwork', 'Graphic Design']::text[], 'approved', false, NULL, '2026-05-19T12:50:25.045Z'),
